//                sPathName_Lot.sprintf("%s\\ByLotID\\%04d\\%02d\\%02d", HTPath, SystemYear, SystemMonth, SystemDate);
//                MyForceDirectories(sPathName_Lot, "TMyStringList::MySaveToFile_2");
